// Data class
 data class Person(val name: String, var age: Int)

// Class with methods
class Calculator {
    fun add(a: Int, b: Int) = a + b
    fun multiply(a: Int, b: Int) = a * b
    fun power(a: Double, b: Double) = Math.pow(a, b)
}

// Object (singleton)
object MathUtils {
    fun factorial(n: Int): Long {
        return if (n <= 1) 1 else n * factorial(n - 1)
    }
}

fun main() {
    val alice = Person("Alice", 30)
    val bob = alice.copy(name = "Bob", age = 25)

    println("Person: $alice")
    println("Bob: $bob")
    println("Same? ${alice == bob}")

    val calc = Calculator()
    println("3 + 4 = ${calc.add(3, 4)}")
    println("6 * 7 = ${calc.multiply(6, 7)}")

    println("Factorial 5 = ${MathUtils.factorial(5)}")
}
